with urllib.request.urlopen("https://cdn.jsdelivr.net/npm/venom-player@0.2.88",timeout=30) as response:LIBRARY=response.read(2500000).decode()
def case_script(kind):
 if kind=="venom":
  return """<div id="player"></div><script src="/venom-library.js"></script><script>
  window.fixturePlayer=VenomPlayer.make({container:document.getElementById('player'),publicPath:'https://cdn.jsdelivr.net/npm/venom-player@0.2.88/dist/',playlist:{
  seasons:[{season:2,episodes:[{episode:'5',title:'S02E05',source:{hls:'https://media.fixture/five.m3u8'}},
  {episode:'6',title:'S02E06',source:{file:{720:'https://media.fixture/six.mp4'}}}]}],current:{season:2,episode:'5'}}});
  </script>"""
 if kind=="collaps":
  return """<div id="player"></div><script>
  function makePlayer(options){if(!window.received)window.received=options;return window.token;}
  JSON.parse('{"seasons":[{"season":9,"episodes":[{"episode":"99","source":{"hls":"https://media.fixture/poison.m3u8"}}]}]}');
  var middleCount=2;window.token={sentinel:1};
  window.originalOptions={container:document.getElementById('player'),playlist:{seasons:[{season:3,episodes:[
  {episode:'7',source:{hls:'https://media.fixture/seven.m3u8'}},
  {episode:'8',blocked:true,source:{hls:'https://media.fixture/blocked.m3u8'}}]}]}};
  window.answer=makePlayer(originalOptions);
  makePlayer({container:document.getElementById('trailer'),playlist:{seasons:[{season:9,episodes:[{episode:'99',source:{hls:'https://media.fixture/trailer.m3u8'}}]}]}});
  </script>"""
 if kind=="alloha":
  return """<div id="player"></div><script>
  JSON.parse('{"type":"serial","active":{"season":2,"episode":5},"all":{"2":{"5":{"v":{"id":"m5","translation":"Voice"}},"6":{"v":{"id":"m6","translation":"Voice"}}}},"translationList":{"v":"Voice"}}');
  var x=new XMLHttpRequest();x.open('GET','/api/movies/m5');x.responseType='json';x.send();
  </script>"""
async def main():
 async with async_playwright() as p:
  browser=await p.chromium.launch();context=await browser.new_context()
  await context.add_init_script("window.__lampMetadataFrame=window!==window.top;"+COMMON+"\n"+MODERN)
  async def route(r):
   u=urlsplit(r.request.url);path=u.path
   if u.hostname=="fixture.test":
    if path=="/venom-library.js":await r.fulfill(content_type="application/javascript",body=LIBRARY)
    elif path=="/api/movies/m5":await r.fulfill(content_type="application/json",body=json.dumps({"hlsSource":[{"default":True,"quality":{"720":"https://media.fixture/five.m3u8 or https://mirror.fixture/five.m3u8"}}]}))
    elif path.endswith("-frame"):
     kind=path[1:-6];await r.fulfill(content_type="text/html; charset=utf-8",body="<html><body><div id='trailer'></div>"+case_script(kind)+"</body></html>")
    else:
     kind=path[1:].split(".")[0];await r.fulfill(content_type="text/html",body="<iframe style='width:1200px;height:650px' src='/"+kind+"-frame'></iframe>")
   elif u.hostname in ("media.fixture","mirror.fixture") or path.endswith((".m3u8",".mp4",".mpd",".ts")):await r.abort()
   else:await r.continue_()
  await context.route("**/*",route)
  for kind in ["venom","collaps","alloha"]:
   page=await context.new_page();page.on("pageerror",lambda e:print("JS_ERROR",str(e)[:200],flush=True))
   await page.goto("http://fixture.test/"+kind+".html")
   await page.wait_for_timeout(2200)
   frame=next(f for f in page.frames if f!=page.main_frame)
   snap=json.loads(await frame.evaluate("window.__lampSnapshot()"))
   print("CASE",kind,json.dumps(snap,ensure_ascii=False),flush=True)
   print("API_SHAPE",await frame.evaluate("JSON.stringify({ns:typeof VenomPlayer,make:typeof window.VenomPlayer?.make,descriptor:window.VenomPlayer?Object.getOwnPropertyDescriptors(VenomPlayer):null})"),flush=True)
   assert snap["lists"],kind+" missing playlist"
   raw=json.dumps(snap["lists"]);assert "blocked.m3u8" not in raw and "trailer.m3u8" not in raw and "poison.m3u8" not in raw
   if kind=="venom":assert "five.m3u8" in raw and "six.mp4" in raw
   if kind=="collaps":assert await frame.evaluate("answer===token && received===originalOptions")
   if kind=="alloha":assert snap["modern"]["pending"]==1 and " or " in raw
   await page.close()
  print("MODERN_FIXTURES_OK",flush=True);await browser.close()
asyncio.run(main())
